function getCurrentData() {
    if (currentSubclass === '189') return DATA_189;
    if (currentSubclass === '491') return DATA_491;
    return DATA_190;
}

// Initialize Dropdown
function initSelect() {
    const currentData = getCurrentData();
    const months = currentData.months;
    const select = document.getElementById('lodged-select');
    select.innerHTML = '';
    
    months.forEach((m, idx) => {
        const opt = document.createElement('option');
        opt.value = idx;
        if (m.startsWith('<=')) {
            opt.textContent = currentSubclass === '190' ? '2025年06月及以前 (旧案积压)' : '2024年06月及以前 (旧案积压)';
        } else {
            opt.textContent = m.replace('-', '年') + '月';
        }
        // Default selection: 2026-01 for 190, 2025-06 for 491
        if (currentSubclass === '189' && m === '2026-06') opt.selected = true;
        if (currentSubclass === '190' && m === '2026-01') opt.selected = true;
        if (currentSubclass === '491' && m === '2025-06') opt.selected = true;
        select.appendChild(opt);
    });
}

// Determine Tier
function getTier(location, occ, family) {
    if (occ === 'priority') return 1;
    if (location === 'onshore') return 2;
    if (family === 'single') return 3;
    return 4;
}

// Parse string to Date
function parseDate(dateStr) {
    if (!dateStr || dateStr === '-') return null;
    const p = dateStr.split('-');
    return new Date(parseInt(p[0]), parseInt(p[1]) - 1, parseInt(p[2]));
}

// Working Days Count
function countWorkdays(start, end) {
    if (start >= end) return 0;
    let count = 0;
    let cur = new Date(start.getTime());
    while (cur < end) {
        cur.setDate(cur.getDate() + 1);
        const day = cur.getDay();
        if (day !== 0 && day !== 6) count++;
    }
    return count;
}

function subtractWorkdays(startDate, numDays) {
    let d = new Date(startDate.getTime());
    let counted = 0;
    while (counted < numDays) {
        d.setDate(d.getDate() - 1);
        const day = d.getDay();
        if (day !== 0 && day !== 6) counted++;
    }
    return d;
}

function formatDateStr(d) {
    const y = d.getFullYear();
    const m = String(d.getMonth() + 1).padStart(2, '0');
    const day = String(d.getDate()).padStart(2, '0');
    return `${y}-${m}-${day}`;
}

// Main Calculation
function calculateForecast() {
    const currentData = getCurrentData();
    const months = currentData.months;
    const mIdx = parseInt(document.getElementById('lodged-select').value);
    const location = document.querySelector('input[name="location"]:checked').value;
    const occ = document.querySelector('input[name="occupation"]:checked').value;
    const family = document.querySelector('input[name="family"]:checked').value;

    const tier = getTier(location, occ, family);
    updateTierStrip(tier);

    const monthLabel = months[mIdx] || '';
    const isClearedT2 = (currentSubclass === '190' && tier === 2 && mIdx < 7) ||
                        (currentSubclass === '189' && tier === 2 && mIdx < 20);

    const m1_info = currentData.m1[tier][mIdx];
    const m2_info = currentData.m2[tier][mIdx];
    const m3_info = currentData.m3[tier][mIdx];
    const m4_info = currentData.m4[tier][mIdx];

    const m1_date = m1_info ? m1_info.date : '-';
    const m2_date = m2_info ? m2_info.date : '-';
    const m3_date = m3_info ? m3_info.date : '-';
    const m4_date = m4_info ? m4_info.date : '-';

    document.getElementById('m1-date').textContent = isClearedT2 ? 'MD119已完成' : m1_date;
    document.getElementById('m2-date').textContent = isClearedT2 ? 'MD119已完成' : m2_date;
    document.getElementById('m3-date').textContent = isClearedT2 ? 'MD119已完成' : m3_date;
    document.getElementById('m4-date').textContent = isClearedT2 ? 'MD119已完成' : m4_date;

    const grantDisplay = document.getElementById('grant-date-display');
    const daysEl = document.getElementById('days-remaining');
    const workdaysEl = document.getElementById('workdays-remaining');
    const fyEl = document.getElementById('fy-label');
    const barEl = document.getElementById('progress-bar');
    const badgeEl = document.getElementById('progress-badge');
    const pctTextEl = document.getElementById('progress-pct-text');
    const labelStart = document.getElementById('label-start');
    const labelEnd = document.getElementById('label-end');
    const dgCard = document.getElementById('direct-grant-card');
    const dgBadge = document.getElementById('dg-badge');
    const dgText = document.getElementById('dg-text');
    const quotaWarn = document.getElementById('quota-warning-banner');

    // Parse applicant lodgement date
    let lDate;
    if (monthLabel.startsWith('<=')) {
        lDate = currentSubclass === '190' ? new Date(2025, 4, 1) : new Date(2024, 4, 1);
        labelStart.textContent = '递交申请 (' + (currentSubclass === '190' ? '≤2025-06' : '≤2024-06') + ')';
    } else {
        const parts = monthLabel.split('-');
        lDate = new Date(parseInt(parts[0]), parseInt(parts[1]) - 1, 1);
        labelStart.textContent = '递交申请 (' + monthLabel + ')';
    }

    // Check Quota Exhaustion for 491 Offshore
    const isExhausted = (currentSubclass === '491' && tier >= 3 && m2_info && m2_info.quota_exhausted);
    if (isExhausted) {
        quotaWarn.classList.add('visible');
    } else {
        quotaWarn.classList.remove('visible');
    }

    if (isClearedT2) {
        grantDisplay.textContent = 'MD119 阶段已审理完成';
        grantDisplay.className = 'hero-date cleared';
        daysEl.textContent = '0 天 (在池中)';
        workdaysEl.textContent = '等待系统发信';
        fyEl.textContent = 'FY27 境内';

        barEl.style.width = '100%';
        barEl.className = 'progress-bar complete';
        badgeEl.className = 'progress-badge complete';
        pctTextEl.textContent = '已完成 100%';
        labelEnd.textContent = '审理完毕 (池中待信)';

        dgCard.style.display = 'none';
    } else if (m2_date && m2_date !== '-') {
        grantDisplay.textContent = m2_date;
        grantDisplay.className = 'hero-date';

        const gDate = parseDate(m2_date);
        const diffTime = gDate - today;
        const diffDays = Math.max(0, Math.ceil(diffTime / (1000 * 60 * 60 * 24)));
        const workdays = countWorkdays(today, gDate);

        daysEl.textContent = diffDays + ' 天';
        workdaysEl.textContent = workdays + ' 个工作日';
        
        let fyText = (m2_info ? m2_info.fy : 'FY27') + (tier === 1 ? (location === 'onshore' ? ' 境内' : ' 境外') : (tier === 2 ? ' 境内' : ' 境外'));
        if (isExhausted) {
            fyText += ' (顺延)';
        }
        fyEl.textContent = fyText;

        // Precise percentage calculation based on actual timeline
        const totalSpan = gDate.getTime() - lDate.getTime();
        const elapsed = Math.max(0, today.getTime() - lDate.getTime());
        let pct = Math.round((elapsed / totalSpan) * 100);
        pct = Math.max(8, Math.min(99, pct));

        barEl.style.width = pct + '%';
        if (pct >= 90) {
            barEl.className = 'progress-bar complete';
            badgeEl.className = 'progress-badge complete';
            pctTextEl.textContent = '临近获批 · 已完成 ' + pct + '%';
        } else {
            barEl.className = 'progress-bar';
            badgeEl.className = 'progress-badge';
            pctTextEl.textContent = '排期已完成 ' + pct + '%';
        }

        labelEnd.textContent = '预计获批 (' + m2_date + ')';

        // Direct Grant Fast-track Window
        dgCard.style.display = 'flex';
        if (gDate <= today) {
            dgText.innerHTML = '该月份已整体处于<strong>官方批签实盘验证窗口</strong>。近期密集放量，无补料直签率显著提升。';
        } else {
            const earlyD = subtractWorkdays(gDate, 7);
            const lateD = subtractWorkdays(gDate, 3);
            const earlyStr = formatDateStr(earlyD);
            const lateStr = formatDateStr(lateD);
            let note = '';
            if (tier === 1) {
                note = '<br><span style="color:#D97706;font-size:11px;font-weight:600;">🩺 极速通道提示：若属于医疗护理或教师类急需职业，官方数据实测获批仅需 2~4 个月（实测 491/190 优先类秒批），实际获批预计将显著早于基准排期！</span>';
            } else if (isExhausted) {
                note = '<br><span style="color:#B45309;font-size:11px;font-weight:600;">⚠️ 跨财年提示：受 491 境外配额熔断影响，当前批签节点处于 FY28 周期，建议提前确认材料完整性，静待新财年首批释放。</span>';
            }
            dgText.innerHTML = '免补料直签 (Direct Grant) 先锋窗口：若材料齐全无需s56补料，预计可提前至 <strong class="dg-date-highlight">' + earlyStr + ' ~ ' + lateStr + '</strong> 率先突围下签！' + note;
        }
    } else {
        grantDisplay.textContent = '待排期';
        daysEl.textContent = '-';
        workdaysEl.textContent = '-';
        fyEl.textContent = '-';
        barEl.style.width = '10%';
        barEl.className = 'progress-bar';
        badgeEl.className = 'progress-badge';
        pctTextEl.textContent = '排期中 10%';
        labelEnd.textContent = '预计获批';

        dgCard.style.display = 'none';
    }

    // Update Mental Massage & Encouragement Text
    updateBlessingMsg(tier, isClearedT2);
}

